/**
 * THE VESSELS, PAINTED
 *
 * Six of the seven, cut from a supplied sheet: onggi, glass fermenter, cedar
 * muro, thermal chamber, the rope-bound cedar tub and the oak cask. The Cedar
 * Tray was not on the sheet and keeps its line drawing; `VesselArt` and
 * `IsoVessel` both fall back to it when a vessel has no entry here.
 *
 * The sheet came as JPEG on a cream ground, so each one was keyed at build time:
 * the ground flooded in from the cell edges, and the anti-aliased rim un-mixed
 * from the cream so there is no pale halo on the dark room. WebP with alpha,
 * all six in 58 KB. Data URIs for the same reason as every other plate: the
 * published page's CSP blocks external images.
 *
 * A painting never takes the ink filter; see `.iso-lift.painted`.
 */
export const VESSEL_ART: Record<string, { w: number; h: number; src: string }> = {
  mason_jar: { w: 163, h: 322, src: 'data:image/webp;base64,' },
  onggi: { w: 254, h: 315, src: 'data:image/webp;base64,' },
  koji_muro: { w: 271, h: 322, src: 'data:image/webp;base64,' },
  incubator: { w: 250, h: 305, src: 'data:image/webp;base64,' },
  cedar_barrel: { w: 234, h: 297, src: 'data:image/webp;base64,' },
  oak_cask: { w: 217, h: 314, src: 'data:image/webp;base64,' },
};
